  "simulation.help.risk.label.conception_rate": "గర్భధారణ రేటు",
  "simulation.help.risk.label.fodder_yield": "మేత దిగుబడి",
  "simulation.help.risk.label.operating_cost": "నిర్వహణ ఖర్చు",
  "simulation.help.risk.variable": "{variable}పై అనిశ్చితి: ప్రతి ప్రమాద పునరావృతంలో ప్రస్తుత మూల విలువ చుట్టూ కింది కనిష్ఠ–గరిష్ఠ మధ్య యాదృచ్ఛిక గుణకం ఎంచుకుంటారు. దీని వల్ల మొత్తం ఫారం NPV పంపిణీలో మార్పు తెలుస్తుంది. పరామితిని స్థిరంగా ఉంచడానికి ఆఫ్ చేయండి.",
  "simulation.help.noun.parturition": "ప్రసవం",
  "team.transfer.action": "యాజమాన్యం బదిలీ చేయి",
  "team.transfer.title": "ఫారం యాజమాన్యం బదిలీ",
  "team.transfer.description": "వెబ్ పాస్‌వర్డ్ వాడుతూ మొదటి పాస్‌వర్డ్ మార్పు పూర్తి చేసిన క్రియాశీల సభ్యునికి యాజమాన్యం బదిలీ అవుతుంది. టాబ్లెట్ పిన్ సభ్యులను ఎంచుకోలేరు. సర్వర్ వారి ప్రస్తుత అర్హతను ధృవీకరిస్తుంది. కొత్త యజమాని ప్రవేశ సెషన్‌లు రద్దవుతాయి; వారు మళ్లీ ప్రవేశించాలి. మీకు యజమాని అధికారం పోతుంది; ఈ ఫారానికి ప్రవేశం కూడా పోవచ్చు. నిర్వహణ రికార్డులు ఫారంతోనే ఉంటాయి.",
  "team.transfer.noRecipients": "పాస్‌వర్డ్ వాడుతున్నట్లు నిర్ధారించిన క్రియాశీల సభ్యులు లేరు. తగిన సభ్యుని క్రియాశీలం చేసి ముందుగా పాస్‌వర్డ్ మార్పు పూర్తి చేయించండి.",
  "team.transfer.recipient": "కొత్త ఫారం యజమాని",
