  "team.transfer.confirm": "ఎంచుకున్న సభ్యుడు యజమాని అవుతారని, నాకు యజమాని అధికారం పోతుందని అర్థం చేసుకున్నాను.",
  "team.transfer.transferring": "యాజమాన్యం బదిలీ జరుగుతోంది…",
  "team.transfer.success": "ఫారం యాజమాన్యం బదిలీ అయింది. మీకు ప్రవేశం ఉన్న ఫారాన్ని ఎంచుకోండి.",
  "team.pin.show": "పిన్ చూపించు",
  "team.pin.hide": "పిన్ దాచు",
  "simulation.narrative.title.overview": "అవలోకనం",
  "simulation.narrative.title.herd_trajectory": "మంద పెరుగుదల",
  "simulation.narrative.title.revenue_mix": "ఆదాయ వనరులు",
  "simulation.narrative.title.cost_mix": "ఖర్చుల వివరాలు",
  "simulation.narrative.title.viability_verdict": "ప్రాజెక్టు సాధ్యత",
  "simulation.narrative.title.risks": "నష్టభయాలు",
  "simulation.narrative.title.optimization": "ఉత్తమ ప్రణాళిక ఎంపిక",
  "simulation.narrative.title.unknown": "నివేదిక విభాగం",
  "simulation.narrative.unknown": "ఈ పేరాకు పూర్తి అనువాదం ఇంకా అందుబాటులో లేదు. నిర్ణయం తీసుకునే ముందు దాని అసలు ఆంగ్ల పాఠాన్ని పరిశీలించండి.",
  "simulation.narrative.overview": "ఈ అంచనా {start} నుంచి {months} నెలలు ({years} సంవత్సరాలు) సాగుతుంది. ప్రారంభంలో {does} ఆడ మేకలు, {bucks} మగ మేకలు{young} ఉంటాయి; మొదటి నెలలో మొత్తం {head} మేకలు ఉంటాయి.{events}",
  "simulation.narrative.young": ", అలాగే {kids} పిల్లలు, పాలు మానిన {weaners} పిల్లలు, పెరుగుతున్న {growers} మేకలు",
  "simulation.narrative.events": " మధ్యలో మందకు సంబంధించిన {count} చర్యలు నిర్ణయించారు: {actions}.",
